import docx
from docx.table import Table
from docx.text.paragraph import Paragraph
from docx.oxml.ns import qn

doc = docx.Document(r'inputs/candidate/0058_R06.docx')
body = doc.element.body
ti=0
for child in body.iterchildren():
    if child.tag == qn('w:p'):
        p = Paragraph(child, doc)
        if '空白表' in p.text:
            print('PARA:', repr(p.text[:200]))
    elif child.tag == qn('w:tbl'):
        t = Table(child, doc)
        ti+=1
        for r in t.rows:
            for c in r.cells:
                if '空白表' in c.text:
                    print(f'TABLE{ti} CELL:', repr(c.text[:200]))
